// Package macloc 实现 MAC 地址厂商（OUI）查询命令。
// 对应网页版：network/mac-lookup-tool.html（MAC厂商查询）
//
// 数据来源: IEEE OUI 官方列表 http://standards-oui.ieee.org/oui/oui.txt，
// 提取 (前缀, 厂商) 后 gzip + base64 内嵌于源码常量，查询无需联网。
//
// 用法：
//
//	lyntoolbox macloc 28:6F:B9:xx:xx:xx
//	lyntoolbox macloc -f maclist.txt
//	lyntoolbox macloc 286fb9xxxxxx -fmt
package macloc

import (
	"bytes"
	"compress/gzip"
	"encoding/base64"
	"flag"
	"fmt"
	"io"
	"net/http"
	"os"
	"strings"
	"time"
)

const (
	Name  = "macloc"
	Desc  = "MAC 地址厂商查询（内嵌 IEEE OUI 离线库，支持批量）"
	Usage = `用法: lyntoolbox macloc [-fmt] [-f 文件] [MAC地址]

参数:
  -f    从文件批量查询，每行一个 MAC
  -fmt  规范化输出（大写冒号形式 + 厂商）
  MAC   待查询的 MAC 地址，支持 28:6F:B9:... / 28-6F-B9-... / 286F.B9xx.xx / 286FB9xxxxxx 等写法

说明: 内嵌 IEEE OUI 离线数据库（standards-oui.ieee.org/oui/oui.txt），查询无需联网；
若内嵌数据缺失则回退调用 https://api.macvendors.com（需联网，限速 1 次/秒）。`
)

// ouiB64 内嵌 OUI 数据（gzip+base64，行格式 "AABBCC|厂商"）
const ouiB64 = ``

// Run 执行命令，返回退出码。
func Run(args []string) int {
	fs := flag.NewFlagSet(Name, flag.ContinueOnError)
	file := fs.String("f", "", "批量查询文件（每行一个 MAC）")
	fmtMode := fs.Bool("fmt", false, "规范化输出")
	fs.Usage = func() { fmt.Print(Usage + "\n") }

	// 允许位置参数后仍跟选项（如: macloc 28:6F:B9:xx:xx:xx -fmt）
	rest := args
	var positionals []string
	for {
		if err := fs.Parse(rest); err != nil {
			if err == flag.ErrHelp {
				return 0
			}
			return 2
		}
		rem := fs.Args()
		if len(rem) == 0 {
			break
		}
		positionals = append(positionals, rem[0])
		rest = rem[1:]
	}

	var macs []string
	switch {
	case *file != "":
		b, err := os.ReadFile(*file)
		if err != nil {
			fmt.Fprintf(os.Stderr, "读取文件失败: %v\n", err)
			return 1
		}
		for _, line := range strings.Split(string(b), "\n") {
			line = strings.TrimSpace(line)
			if line != "" {
				macs = append(macs, line)
			}
		}
		if len(macs) == 0 {
			fmt.Fprintln(os.Stderr, "错误: 文件中没有非空行")
			return 1
		}
	case len(positionals) > 0:
		macs = positionals
	default:
		fmt.Fprintln(os.Stderr, "错误: 需要一个 MAC 地址或 -f 文件")
		fmt.Fprintln(os.Stderr, "（lyntoolbox macloc -h 查看帮助）")
		return 2
	}

	table := loadOUI()
	live := table == nil
	if live {
		fmt.Fprintln(os.Stderr, "提示: 内嵌数据缺失，回退在线 API api.macvendors.com（需联网，限速 1 次/秒）")
	}

	exitCode := 0
	for i, raw := range macs {
		if i > 0 {
			if live {
				time.Sleep(1100 * time.Millisecond) // 在线 API 限速 1 次/秒
			} else if !*fmtMode {
				fmt.Println()
			}
		}
		full, prefix, ok := normalizeMAC(raw)
		if !ok {
			fmt.Fprintf(os.Stderr, "MAC 格式无效: %s\n", raw)
			exitCode = 1
			continue
		}
		normalized := colonForm(full)
		var vendor string
		if table != nil {
			v, found := table[prefix]
			if !found {
				vendor = "未找到该 OUI 对应的厂商记录"
				if exitCode == 0 {
					exitCode = 1
				}
			} else {
				vendor = v
			}
		} else {
			v, code := liveLookup(prefix)
			vendor = v
			if code != 0 && exitCode == 0 {
				exitCode = 1
			}
		}
		if *fmtMode {
			fmt.Printf("%s %s\n", normalized, vendor)
			continue
		}
		if i == 0 && !live {
			fmt.Println("数据源: 内嵌 IEEE OUI 离线库")
		}
		fmt.Printf("输入:        %s\n", raw)
		fmt.Printf("规范化 MAC:  %s\n", normalized)
		fmt.Printf("OUI 前缀:    %s\n", prefix)
		fmt.Printf("厂商:        %s\n", vendor)
	}
	return exitCode
}

// loadOUI 解压内嵌数据为 map；数据缺失时返回 nil
func loadOUI() map[string]string {
	if ouiB64 == "" || strings.Contains(ouiB64, "PLACEHOLDER") {
		return nil
	}
	raw, err := base64.StdEncoding.DecodeString(ouiB64)
	if err != nil {
		return nil
	}
	zr, err := gzip.NewReader(bytes.NewReader(raw))
	if err != nil {
		return nil
	}
	defer zr.Close()
	data, err := io.ReadAll(zr)
	if err != nil {
		return nil
	}
	m := make(map[string]string, 45000)
	for _, line := range strings.Split(string(data), "\n") {
		if line == "" {
			continue
		}
		if i := strings.IndexByte(line, '|'); i > 0 {
			m[line[:i]] = line[i+1:]
		}
	}
	return m
}

// liveLookup 在线 API 查询（回退路线）
func liveLookup(prefix string) (string, int) {
	client := &http.Client{Timeout: 15 * time.Second}
	req, err := http.NewRequest(http.MethodGet, "https://api.macvendors.com/"+prefix, nil)
	if err != nil {
		return "构造请求失败: " + err.Error(), 1
	}
	req.Header.Set("User-Agent", "LynToolBox/1.0")
	resp, err := client.Do(req)
	if err != nil {
		return "在线查询失败（需联网）: " + err.Error(), 1
	}
	defer resp.Body.Close()
	b, _ := io.ReadAll(resp.Body)
	switch resp.StatusCode {
	case http.StatusOK:
		return strings.TrimSpace(string(b)), 0
	case http.StatusNotFound:
		return "未找到该 OUI 对应的厂商记录", 1
	case http.StatusTooManyRequests:
		return "查询过于频繁（api.macvendors.com 限速 1 次/秒）", 1
	default:
		return fmt.Sprintf("查询失败: HTTP %d", resp.StatusCode), 1
	}
}

// normalizeMAC 清洗 MAC，返回 12 位大写十六进制与 6 位 OUI 前缀
func normalizeMAC(s string) (full, prefix string, ok bool) {
	var sb strings.Builder
	for _, r := range s {
		if r == ':' || r == '-' || r == '.' || r == ' ' {
			continue
		}
		sb.WriteRune(r)
	}
	clean := strings.ToUpper(sb.String())
	if len(clean) != 12 {
		return "", "", false
	}
	for _, c := range clean {
		if !((c >= '0' && c <= '9') || (c >= 'A' && c <= 'F')) {
			return "", "", false
		}
	}
	return clean, clean[:6], true
}

// colonForm 大写冒号形式 28:6F:B9:xx:xx:xx
func colonForm(full string) string {
	var parts []string
	for i := 0; i < len(full); i += 2 {
		parts = append(parts, full[i:i+2])
	}
	return strings.Join(parts, ":")
}
